/*	=== Turn a failure into an alert a person can act on ===	*/
/*	The error trigger payload carries workflow and execution metadata only, never the failing	*/
/*	workflow's data. Reading the values that broke means fetching the execution through the n8n API,	*/
/*	which needs an n8n API credential. So the alert links to the failed run instead of pretending to	*/
/*	diagnose it.	*/
/*	The trigger is read BY NAME, never from $input: the input here is Config, and reading $input would	*/
/*	label every real failure as a hand test.	*/
const config_obj = $('Config').first().json;

let payload_obj = {};
let fromErrorTrigger_bln = false;
if ($('On QR Workflow Failure').isExecuted)
{
	payload_obj = $('On QR Workflow Failure').first().json || {};
	fromErrorTrigger_bln = true;
}

const workflow_obj = payload_obj.workflow || {};
const execution_obj = payload_obj.execution || {};
const trigger_obj = payload_obj.trigger || {};
const error_obj = execution_obj.error || trigger_obj.error || {};

const isTest_bln = !fromErrorTrigger_bln;
const isUnidentified_bln = fromErrorTrigger_bln && !execution_obj.id && !workflow_obj.id;
const failedAt_str = new Date().toISOString();

let link_str = String(execution_obj.url || '').trim();
if (link_str === '' && workflow_obj.id && execution_obj.id)
{
	link_str = String(config_obj.N8N_BASE_URL) + '/workflow/' + workflow_obj.id + '/executions/' + execution_obj.id;
}

let name_str = String(workflow_obj.name || '');
if (name_str === '')
{
	name_str = isTest_bln ? '(handler tested by hand, no real failure)' : 'UNIDENTIFIED workflow';
}

let message_str = String(error_obj.message || '');
if (message_str === '')
{
	message_str = isTest_bln
		? 'No error payload, so this is a manual test of the handler itself.'
		: 'A failure was reported with no message. Treat it as real and check recent executions.';
}

/*	What the failure means in practice depends on which workflow broke. Workflow names must keep	*/
/*	their leading number (1.0, 2.0 ...) for this to work.	*/
let impact_str = 'Open the execution to see which node failed.';
if (name_str.indexOf('3.0') === 0)
{
	impact_str = 'A delegate saw an error page instead of a result, so their attendance may not be marked. Check the execution, then check that person in Administrate by hand.';
} else if (name_str.indexOf('4.0') === 0) {
	impact_str = 'The morning reconciliation report did not go out.';
} else if (name_str.indexOf('5.0') === 0) {
	impact_str = 'A member of staff saw an error instead of the page. It is read-only, so nothing was changed.';
} else if (name_str.indexOf('1.0') === 0 || name_str.indexOf('2.0') === 0) {
	impact_str = 'A QR code link or page could not be produced for an event.';
}

let subject_str = String(config_obj.SUBJECT_PREFIX) + ' FAILED: ' + name_str;
if (isTest_bln)
{
	subject_str = String(config_obj.SUBJECT_PREFIX) + ' TEST alert, no action needed';
} else if (isUnidentified_bln) {
	subject_str = String(config_obj.SUBJECT_PREFIX) + ' FAILED: workflow could not be identified';
}

const lines_ary = [];
if (isTest_bln)
{
	lines_ary.push('This is a TEST of the failure handler. Nothing has failed and no action is needed.');
} else {
	lines_ary.push('A QR check-in workflow failed.');
}
lines_ary.push('');
lines_ary.push('Workflow:  ' + name_str);
lines_ary.push('Failed at: ' + failedAt_str);
lines_ary.push('Last node: ' + String(execution_obj.lastNodeExecuted || 'unknown'));
lines_ary.push('Mode:      ' + String(execution_obj.mode || (isTest_bln ? 'manual test' : 'unknown')));
lines_ary.push('');
lines_ary.push('Message:');
lines_ary.push(message_str);
lines_ary.push('');
if (!isTest_bln)
{
	lines_ary.push('What it means:');
	lines_ary.push(impact_str);
	lines_ary.push('');
}
if (link_str !== '')
{
	lines_ary.push('Execution: ' + link_str);
}

return [{ json: {
	subject: subject_str,
	body: lines_ary.join('\n'),
	isTest: isTest_bln,
	workflowName: name_str,
	executionUrl: link_str,
	message: message_str
} }];
